// Signal names the signals a graceful-shutdown handler typically waits for.
// Use these values with signal.WaitFor and signal.Context instead of
// importing syscall or os.Signal directly.
type Signal string

const (
	SignalInterrupt    Signal = "interrupt"
	SignalTerminate    Signal = "terminate"
	SignalHangup       Signal = "hangup"
	SignalUserDefined1 Signal = "user-defined-1"
	SignalUserDefined2 Signal = "user-defined-2"
)

